/*
Gradient Clock -- Svenofnine / Erfurt 2024
https://www.shadertoy.com/view/l33yzs
*/

#define R iResolution          // shorten the symbol to R

const    
 uint[] digits = uint[] (
     488166958u, // 0
     474091660u, // 1
    1057503294u, // 2
    1007728702u, // 3
      70240582u, // 4
    1007745567u, // 5
     488176142u, // 6
     545392703u, // 7
     488159790u, // 8
     471320110u, // 9
     134221824u, // :
             0u  // space
);

// using a uint to draw a 5x6 dot matrix
float char5x6(vec2 d, uint bits) {
    return 
    ((d.x<0.) || (d.x>5.) || (d.y>0.) || (d.y<-6.)) 
    ? 0. 
    : (( bits >> ( int( floor(-d.y) * 5. + floor(5.-d.x) ) ) & 1u) == 1u) 
        ? smoothstep(0.7, 0., distance(vec2(0.5),fract(d)) ) 
        : 0.;
}

// split seconds in hours, minutes and seconds 
vec3 get_hms( float seconds ){
    return vec3 ( seconds/3600., mod(seconds, 3600.) / 60., mod(seconds, 60.) ); // vec3(hours, mins, secs)
}

// convert cartesic to polar coordinates (.x = normalized angle 0...1, .y = length)
vec2 polar ( vec2 cartesic ) {
    return vec2( atan(cartesic.x, cartesic.y)/6.28318530718, sqrt(cartesic.x*cartesic.x+cartesic.y*cartesic.y));
}

// build the int[]-string to write and return only a specific char5x6() at a time
// hms_time is vec3(hour 0..23, mins 0..59, secs 0..59)
float write_time(vec2 d, float seconds ) {
    ivec3 hms = ivec3(get_hms(seconds));
    ivec3 hms1 = hms/10;
    ivec3 hms2 = hms%10;
    int bc = fract(iTime)>0.5 ? 10 : 11;   // bc = blinking colon
    int[] s = int[8] ( hms1.x, hms2.x, bc, hms1.y, hms2.y, bc, hms1.z, hms2.z ); 
    int i = int(floor(d.x/6.)); 
    return ((i>=0) && (i<8)) ? char5x6(vec2(d.x-float(i)*6.,d.y), digits[s[i]] ) : 0.;
}

void mainImage( out vec4 C, in vec2 S ) {  // C=Color of the pixel, S=Screen coordinate of the pixel
    // init canvas
    vec2 uv = S.xy/vec2(R.y);
    vec2 center = .5*R.xy/R.y;
    vec2 rel_xy = (uv-center)*100.;    

    // calc analog hands
    vec3 hms = get_hms(iDate.w);        // split seconds count to hms = vec3(hours, mins, secs)
    hms.x = mod(hms.x, 12.);            // make sure that the hour hand will go 360 degrees in 12 hours
    hms /= vec3(12.,60.,60.);           // normalize all hands to 0. ... 1.

    // draw analog hands
    vec2 p = polar(uv-center);          // calculate the polar coordinates from center to uv; with normalized angle 0. ... 1.
    hms = fract(vec3(1.-p.x)+hms);      // calculate the angle of the hands, gradient will start at the right angle (clock hands)
    C = vec4( vec3( smoothstep( 1., 0., hms ) ), 1. );  // set the colors for all three hands

    // the pulsing horizontal stripe
    C *= vec4(
        vec3( 
            .8 - 0.2 * sin( uv.x+iTime )   // brightness go from 0.6 .. 1.0
            * ( smoothstep(0.03, 0.04, uv.y) - smoothstep(0.16, 0.17, uv.y) )   // affect only pixels with this uv.y 
        ), 
        1.
    ); 

    // draw digital clock with inverse colors
    vec4 inv_C = vec4( 1.-C.rrr, 1.);
    C = mix( C, inv_C, write_time( rel_xy+vec2(20.,35.), iDate.w ));   // big numbers = current time
    C = mix( C, inv_C, write_time( rel_xy*2.+vec2(-7.,85.), iTime ));  // small numbers = run time
}
